package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for FastMath.signum(double)
 */
public class FastMath_signum_TriageGen2Test {

    private static final double DELTA = 0.0;

    @Test
    public void testSignumPositive() {
        // Tests (a > 0.0) branch returning 1.0
        assertEquals(1.0, FastMath.signum(1.0), DELTA);
        assertEquals(1.0, FastMath.signum(Double.MAX_VALUE), DELTA);
        assertEquals(1.0, FastMath.signum(0.0000000001), DELTA);
    }

    @Test
    public void testSignumNegative() {
        // Tests (a < 0.0) branch returning -1.0
        assertEquals(-1.0, FastMath.signum(-1.0), DELTA);
        assertEquals(-1.0, FastMath.signum(-Double.MAX_VALUE), DELTA);
        assertEquals(-1.0, FastMath.signum(-0.0000000001), DELTA);
    }

    @Test
    public void testSignumZero() {
        // Tests (a == 0.0) and isNaN(a) is false branch returning 0.0
        assertEquals(0.0, FastMath.signum(0.0), DELTA);
        // Note: In Java, -0.0 < 0.0 is false and -0.0 > 0.0 is false, 
        // so signum(-0.0) should return 0.0 based on the logic provided.
        assertEquals(0.0, FastMath.signum(-0.0), DELTA);
    }

    @Test
    public void testSignumNaN() {
        // Tests (a == 0.0) and isNaN(a) is true branch returning NaN
        assertEquals(Double.NaN, FastMath.signum(Double.NaN), DELTA);
    }
}
